(48640,'importacao_divergente','Importação divergente',1,'A Super Crono exibe Maratona Internacional de Foz do Iguaçu 5K, modalidade 5KM. Neste ID há 1.233 linhas marcadas 42 km; 268 passam pela regra atual, incluindo 105 REVEZAMENTO. Tempos mínimos de 30 segundos evidenciam outra divergência, cuja causa não foi diagnosticada.','Conferir associação da prova, modalidade, conclusão e conversão dos tempos; recolher novamente a fonte correta. Não trocar a distância nem excluir só os tempos rápidos.','["https://www.supercrono.com.br/resultados/result/#/maratona-internacional-de-foz-do-iguau-5k"]'::jsonb)),
fonte AS(SELECT result->'rows' AS r FROM estudo.notebook_runs WHERE id=212 AND cell_id=404 AND cell_version=1 AND status='ok' AND frozen AND NOT truncated AND row_count=16),
linhas AS(SELECT v||jsonb_build_object('grupo',d.grupo,'situacao',d.situacao,'prioridade',d.prioridade,'evidencia',d.evidencia,'proximo_passo',d.proximo_passo,'referencias',d.referencias,'verificado_em','2026-10-06') AS r
 FROM fonte,jsonb_array_elements(fonte.r)v JOIN decisoes d ON d.id_evento=(v->>'id_evento')::bigint),
resumo AS(SELECT r->>'grupo' AS grupo,r->>'situacao' AS situacao,count(*) AS eventos,sum((r->>'elegiveis')::bigint) AS linhas_por_regra FROM linhas GROUP BY r->>'grupo',r->>'situacao')
SELECT jsonb_build_object('corte','2026-09-30','verificado_em','2026-10-06','fonte_auditoria',212,'celula_auditoria',404,
 'regra','Triagem dos 16 IDs com resultados 42–42,2 km e sem percurso rua/km correspondente no congelamento 174. Captura atual 212. Confirmação de distância não certifica terreno, homologação, realização ou captura completa. Linhas por regra reproduzem a regra cadastral anterior; ela ainda admite revezamentos e tipos esportivos incorretos. Sem correções operacionais, exclusões automáticas ou mudança nos indicadores publicados.',
 'total',(SELECT count(*) FROM linhas),'linhas_por_regra',(SELECT sum((r->>'elegiveis')::bigint) FROM linhas),
 'resumo',(SELECT jsonb_agg(to_jsonb(resumo) ORDER BY grupo) FROM resumo),
 'casos',(SELECT jsonb_agg(r ORDER BY r->'prioridade',r->'data_final',r->'id_evento') FROM linhas)) AS payload
 FROM fonte